#!/bin/sh
# Rebuild SHA256SUMS.txt deterministically.
# Excluded, and why each one:
#   SHA256SUMS.txt        - would reference itself (gate G-16)
#   __pycache__/          - interpreter-generated bytecode, not an artifact; its
#                           hash changes with the Python version and it is absent
#                           on a clean checkout
#   logs/report_audit.json
#   logs/qa_behavioural_tests.json
#                         - REGENERATED by every audit/test run. Covering them
#                           meant that running the verification invalidated the
#                           manifest it had just verified: a reviewer on a second
#                           machine saw two spurious FAILED lines. They are run
#                           outputs, not fixed artifacts.
cd "$(dirname "$0")"
find . -type f ! -name 'SHA256SUMS.txt' ! -path './__pycache__/*' \
       ! -path './logs/report_audit.json' ! -path './logs/qa_behavioural_tests.json' \
       -print0 | sort -z | xargs -0 sha256sum > SHA256SUMS.txt
wc -l < SHA256SUMS.txt
